HEX = set(b"0123456789abcdefABCDEF")

def parse(buf):     # strict framing, RFC 9112 6.3
    head, _, rest = buf.partition(b"\r\n\r\n")
    lines, h = head.split(b"\r\n"), {}
    for line in lines[1:]:
        name, colon, value = line.partition(b":")
        if not colon or name != name.strip() or name.lower() in h:
            raise ValueError(f"400: bad field {name!r}")
        h[name.lower()] = value.strip()
    te, cl = h.get(b"transfer-encoding"), h.get(b"content-length")
    if te is not None and cl is not None:
        raise ValueError("400: both TE and CL")
    if te is not None:
        if te.lower() != b"chunked":
            raise ValueError("400: unknown coding")
        body = b""
        while True:
            size, _, rest = rest.partition(b"\r\n")
            if not size or not set(size) <= HEX:
                raise ValueError(f"400: chunk size {size!r}")
            n = int(size, 16)
            if n == 0:
                return lines[0], body, rest[2:]
            body, rest = body + rest[:n], rest[n + 2:]
    if cl is not None and not cl.isdigit():
        raise ValueError(f"400: Content-Length {cl!r}")
    n = int(cl or b"0")
    return lines[0], rest[:n], rest[n:]

print(parse(b"POST /notes HTTP/1.1\r\nTransfer-Encoding: chunked\r\n\r\n"
            b"5\r\nhello\r\n6\r\n world\r\n0\r\n\r\n"))
for bad in (b"Content-Length: 5\r\nTransfer-Encoding: chunked",
            b"Content-Length: +5", b"Transfer-Encoding: chunked\r\n\r\n0x5"):
    try:
        parse(b"POST /notes HTTP/1.1\r\n" + bad + b"\r\n\r\n")
    except ValueError as e:
        print(e)

def fields(head, strip_names, keep="last"):
    h = {}
    for line in head.split("\r\n"):
        name, _, value = line.partition(":")
        name = name.strip() if strip_names else name
        if keep == "first" and name.lower() in h:
            continue
        h[name.lower()] = value.strip()
    return h

def framing(h):
    if h.get("transfer-encoding") == "chunked":
        return "chunked"
    return "length " + h.get("content-length", "0")

def strict(head):      # RFC 9112: reject, never guess
    names = [l.partition(":")[0] for l in head.split("\r\n")]
    if any(n != n.strip() for n in names):
        return "400 (whitespace before colon)"
    low = [n.lower() for n in names]
    if low.count("content-length") > 1:
        return "400 (duplicate Content-Length)"
    if "content-length" in low and "transfer-encoding" in low:
        return "400 (both framing headers)"
    return framing(fields(head, False))

cases = {
    "space before colon": "Content-Length: 6\r\nTransfer-Encoding : chunked",
    "two lengths": "Content-Length: 6\r\nContent-Length: 40",
}
for label, head in cases.items():
    a = framing(fields(head, strip_names=True))
    b = framing(fields(head, strip_names=False, keep="first"))
    print(f"{label:18} A={a:13} B={b:13} strict={strict(head)}")

from collections import Counter

# (upstream connection id, request line) as each tier logged it
front = [("c7", "POST /a HTTP/1.1"), ("c7", "GET /home HTTP/1.1"),
         ("c9", "GET /img/1.png HTTP/1.1"), ("c9", "GET /cart HTTP/1.1")]
back = [("c7", "POST /a HTTP/1.1"), ("c7", "LEFTOVERGET /home HTTP/1.1"),
        ("c9", "GET /img/1.png HTTP/1.1"), ("c9", "GET /admin HTTP/1.1"),
        ("c9", "GET /cart HTTP/1.1")]
KNOWN = {"GET", "HEAD", "POST", "PUT", "DELETE", "PATCH", "OPTIONS"}

f, b = Counter(c for c, _ in front), Counter(c for c, _ in back)
for conn in sorted(set(f) | set(b)):
    if f[conn] != b[conn]:
        print(f"{conn}: front end logged {f[conn]}, back end {b[conn]}")
for conn, line in back:
    if line.split(" ")[0] not in KNOWN:
        print(f"{conn}: unknown method in {line!r}")

# An HTTP/2 request as a front end sees it: fields plus DATA frames.
h2 = {"fields": [(":method", "POST"), (":path", "/a"),
                 (":authority", "s.example"), ("content-length", "0")],
      "data": [b"LEFTOVER"]}            # 8 bytes arrive in DATA frames

def naive_downgrade(req):               # copies fields verbatim
    f = dict(req["fields"])
    lines = [f"{f[':method']} {f[':path']} HTTP/1.1", f"Host: {f[':authority']}"]
    lines += [f"{k}: {v}" for k, v in req["fields"] if not k.startswith(":")]
    return "\r\n".join(lines).encode() + b"\r\n\r\n" + b"".join(req["data"])

def checked_downgrade(req):             # RFC 9113 rules first
    size = sum(len(d) for d in req["data"])
    for k, v in req["fields"]:
        if any(c in v for c in "\r\n\0"):
            raise ValueError("malformed: CR, LF or NUL in a field value")
        if k in ("transfer-encoding", "connection", "keep-alive", "upgrade"):
            raise ValueError(f"malformed: connection-specific field {k}")
        if k == "content-length" and int(v) != size:
            raise ValueError(f"malformed: content-length {v} but DATA is {size}")
    return naive_downgrade(req)

wire = naive_downgrade(h2)
print(wire)
try:
    checked_downgrade(h2)
except ValueError as e:
    print("rejected:", e)

# nginx reverse proxy: speak HTTP/2 to the origin as well
upstream app {
    server 10.0.0.5:8443;
    keepalive 16;
}
server {
    listen 443 ssl;
    http2 on;                     # HTTP/2 from browsers
    location / {
        proxy_pass https://app;
        proxy_http_version 2;     # HTTP/2 to the origin (nginx 1.29.4+)
    }
}

CANONICAL = "shop.example"

def origin(req, trust_xfh):
    host = req["headers"].get("x-forwarded-host") if trust_xfh else None
    host = host or CANONICAL
    body = f'<script src="https://{host}/app.js"></script>'
    return {"status": 200, "cc": "public, max-age=300", "body": body}

class Cache:
    def __init__(self, key_fields):
        self.store, self.key_fields = {}, key_fields
    def key(self, req):
        extra = tuple(req["headers"].get(f, "") for f in self.key_fields)
        return (req["method"], req["host"], req["path"]) + extra
    def get(self, req, upstream):
        k = self.key(req)
        if k in self.store:
            return "HIT ", self.store[k]
        resp = upstream(req)
        if "no-store" not in resp["cc"] and "private" not in resp["cc"]:
            self.store[k] = resp
        return "MISS", resp

def run(label, cache, trust_xfh):
    up = lambda r: origin(r, trust_xfh)
    a = {"method": "GET", "host": CANONICAL, "path": "/",
         "headers": {"x-forwarded-host": "attacker.example"}}
    v = {"method": "GET", "host": CANONICAL, "path": "/", "headers": {}}
    for who, req in (("attacker", a), ("victim  ", v)):
        state, resp = cache.get(req, up)
        print(f"{label} {who} {state} {resp['body']}")

run("vulnerable", Cache([]), trust_xfh=True)
run("keyed     ", Cache(["x-forwarded-host"]), trust_xfh=True)
run("fixed app ", Cache([]), trust_xfh=False)

# RFC 9110 lists these as heuristically cacheable; 400 is not one of them.
HEURISTIC = {200, 203, 204, 206, 300, 301, 308, 404, 405, 410, 414, 501}

def origin(req):
    if len(req.get("x-junk", "")) > 8192:     # origin's header limit: 8 KiB
        return 400, "Bad Request"
    return 200, "the real home page"

def make_cache(cacheable):
    store = {}
    def get(path, req):
        if path in store:
            return "HIT ", store[path]
        status, body = origin(req)
        if status in cacheable:
            store[path] = (status, body)
        return "MISS", (status, body)
    return get

for label, codes in (("caches every status ", set(range(100, 600))),
                     ("caches RFC set only ", HEURISTIC)):
    get = make_cache(codes)
    first = get("/", {"x-junk": "A" * 10000})   # cache allows 16 KiB headers
    later = get("/", {})
    print(label, "first:", first, " everyone after:", later)

import re

def origin(path, user, exact):
    route = path.split(";")[0]                 # origin drops ;params
    ok = route == "/account" if exact else re.match(r"^/account", route)
    if not ok:
        return 404, "text/html", "no-store", "not found"
    if user is None:
        return 302, "text/html", "no-store", "log in first"
    return 200, "text/html", "no-store, private", f"balance of {user}: 1,204"

def cache_by_extension(path, user, store, exact, honour_headers):
    if path in store:
        return "HIT ", store[path]
    status, ctype, cc, body = origin(path, user, exact)
    static = re.search(r"\.(css|js|png)$", path)   # cache sees the whole path
    allowed = not honour_headers or ("no-store" not in cc and "private" not in cc)
    if status == 200 and static and allowed:
        store[path] = (status, body)
    return "MISS", (status, body)

for path in ("/account/x.css", "/account;x.css"):
    for label, exact, honour in (("prefix route, ignores headers", False, False),
                                 ("exact route                  ", True, False),
                                 ("honours Cache-Control        ", False, True)):
        store = {}
        cache_by_extension(path, "victim", store, exact, honour)   # victim clicks
        state, (status, body) = cache_by_extension(path, None, store, exact, honour)
        print(f"{path:15} {label} attacker gets {state} {status} {body}")

# Vulnerable: cache anything that looks static, overriding the origin
location ~* \.(css|js|png)$ {
    proxy_pass http://app;
    proxy_cache static;
    proxy_cache_valid 200 1h;
    proxy_ignore_headers Cache-Control Expires Set-Cookie;
}

# Fixed: cache only a real static directory, and let the origin's
# Cache-Control, Expires and Set-Cookie decide (nginx's default)
location /static/ {
    proxy_pass http://app;
    proxy_cache static;
    proxy_cache_valid 200 1h;
}
location / {
    proxy_pass http://app;          # dynamic pages: no proxy_cache
}
